#include <iostream>
#include <deque>
#include <stack>
#include <algorithm>
template <typename T>
class DequeStackAdapter {
private:
  std::deque<T> data;
public:
  DequeStackAdapter() = default;
  explicit DequeStackAdapter(const std::deque<T>& d) : data(d) {}
  void push(const T& val) { data.push_back(val); }
  void pop() { data.pop_back(); }
  T& top() { return data.back(); }
  bool empty() const { return data.empty(); }
};
int main() {
  std::deque<int> deq = {1, 2, 3, 4, 5};
  DequeStackAdapter<int> stack(deq);
  stack.push(6);
  std::cout << stack.top() << std::endl; // Output: 6
  stack.pop();
  std::cout << stack.top() << std::endl; // Output: 5
  return 0;
}

