static void tfunc(union sigval sv) {
    struct mq_attr attr;
    ssize_t nr;
    void *buf;
    mqd_t mqdes = *((mqd_t *) sv.sival_ptr);
    if (mq_getattr(mqdes, &attr) == -1) handle_error("mq_getattr");
    buf = malloc(attr.mq_msgsize);
    if (buf == NULL) handle_error("malloc");
    nr = mq_receive(mqdes, buf, attr.mq_msgsize, NULL);
    if (nr == -1) handle_error("mq_receive");
    printf("Read %zd bytes from MQ\n", nr);
    free(buf);
    exit(EXIT_SUCCESS);
}

int main(int argc, char *argv[]) {
    mqd_t mqdes;
    struct sigevent sev;
    if (argc != 2) { fprintf(stderr, "Usage: %s <mq-name>\n", argv[0]); exit(EXIT_FAILURE); }
    mqdes = mq_open(argv[1], O_RDONLY);
    if (mqdes == (mqd_t) -1) handle_error("mq_open");
    sev.sigev_notify = SIGEV_THREAD;
    sev.sigev_notify_function = tfunc;
    sev.sigev_notify_attributes = NULL;
    sev.sigev_value.sival_ptr = &mqdes;
    if (mq_notify(mqdes, &sev) == -1) handle_error("mq_notify");
    pause();
}

