  0x00, 0x00, 0x00, 0x00, // Placeholder for address
  0x00, 0x00, 0x00, 0x00, // ...more code...
};

# Relocation process:
# 1. Identify the entry's offset (0x1000)
# 2. Determine the final address of the section (e.g., 0x400000)
# 3. Apply patching based on the type and addend:
# 4. Patching: 0x400000 + 0x10 = 0x400010
# 5. Write 0x400010 to the offset (0x1000)
unsigned int final_address = 0x400000;
code_section[entry.offset] = (final_address + entry.addend) & 0xFF;
code_section[entry.offset + 1] = ((final_address + entry.addend) >> 8) & 0xFF;
code_section[entry.offset + 2] = ((final_address + entry.addend) >> 16) & 0xFF;
code_section[entry.offset + 3] = ((final_address + entry.addend) >> 24) & 0xFF;

