#include <iostream>
#include <vector>
#include <utility> // for std::move

class Buffer {
public:
    int* data;
    size_t size;
    // Constructor
    Buffer(size_t s) : data(new int[s]), size(s) {
        std::cout << "Constructed\n";
    }
    // Destructor
    ~Buffer() { delete[] data; }
    // Copy constructor
    Buffer(const Buffer& other) : data(new int[other.size]), size(other.size) {
        std::copy(other.data, other.data + size, data);
        std::cout << "Copied\n";
    }
    // Move constructor
    Buffer(Buffer&& other) noexcept : data(other.data), size(other.size) {
        other.data = nullptr;
        other.size = 0;
        std::cout << "Moved\n";
    }
    // Move assignment
    Buffer& operator=(Buffer&& other) noexcept {
        if (this != &other) {
            delete[] data;
            data = other.data;
            size = other.size;
            other.data = nullptr;
            other.size = 0;
            std::cout << "Move assigned\n";
        }
        return *this;
    }
};

int main() {
    Buffer buf1(10); // normal construction
    Buffer buf2 = std::move(buf1); // move constructor
    Buffer buf3(5);
    buf3 = std::move(buf2); // move assignment
    return 0;
}

