    std::cout << "Static: " << value << std::endl;
  }
};
struct Base {
  virtual void process() { std::cout << "Base class" << std::endl; }
};
struct Derived : public Base {
  void process() override { std::cout << "Derived class" << std::endl; }
};
int main() {
  StaticPolymorphism<int> intProcessor;
  intProcessor.process(10);
  StaticPolymorphism<double> doubleProcessor;
  doubleProcessor.process(3.14);
  auto start = std::chrono::high_resolution_clock::now();
  Base *basePtr = new Base();
  basePtr->process();
  delete basePtr;
  Base *derivedPtr = new Derived();
  derivedPtr->process();
  delete derivedPtr;
  auto end = std::chrono::high_resolution_clock::now();
  auto duration = std::chrono::duration_cast<std::chrono::microseconds>(end - start);
  std::cout << "Runtime polymorphism execution time: " << duration.count() << " microseconds\n";
  return 0;
}

