    {
        auto ptr1 = std::make_unique<Resource>(); // unique ownership
        ptr1->do_something();
        // Resource will be automatically destroyed when ptr1 goes out of scope
    }
    {
        auto sp1 = std::make_shared<Resource>(); // shared ownership
        std::shared_ptr<Resource> sp2 = sp1; // shared ownership
        sp1->do_something();
        std::cout << "Shared pointers count: " << sp1.use_count() << std::endl;
        // Resource will be destroyed when last shared_ptr goes out of scope
    }
    {
        std::weak_ptr<Resource> wp = sp1; // observer, does not affect reference count
        if (auto sp = wp.lock()) {
            sp->do_something();
        }
    }
    return 0;
}

