class MyInputStream {
public:
    explicit MyInputStream(std::istream& is) : stream(is) {}
    int peek() {
        std::ios::sentry s(stream); // Construct sentry object to manage stream state
        if (!s.good()) {
            return traits::eof(); // Return EOF if stream is not good
        }
        return stream.rdbuf()->sgetc(); // Return current character without extracting
    }
private:
    std::istream& stream;
    using traits = std::char_traits<char>;
};

int main() {
    std::istringstream input("Hello World");
    MyInputStream myStream(input);
    int ch = myStream.peek();
    if (ch != std::char_traits<char>::eof()) {
        std::cout << "Next character is: " << static_cast<char>(ch) << std::endl;
