        }
    }
    ~FileHandle() {  // Destructor releases resource
        if (fp) {
            std::fclose(fp);
        }
    }
    // Provide access to the resource
    FILE* get() const { return fp; }
private:
    FILE* fp;  // Raw pointer managed by RAII
};
int main() {
    try {
        FileHandle file("example.txt");  // Resource acquired here
        // Perform operations, e.g., read from file
        std::fgets(buffer, sizeof(buffer), file.get());
        std::cout << "File content: " << buffer << std::endl;
    } catch (const std::exception& e) {
        std::cerr << "Exception: " << e.what() << std::endl;
    }
    // Destructor of FileHandle is called automatically on scope exit
    return 0;
}

