int current_element = 0;
int total_element = 128;
char *dynamic = malloc(total_element * sizeof(char));
void add_element(char c) {
    if (current_element >= total_element) {
        char *temp = realloc(dynamic, (total_element * 2) * sizeof(char));
        if (temp == NULL) {
            // handle reallocation failure
            return;
        }
        dynamic = temp;
        total_element *= 2;
    }
    dynamic[current_element++] = c;
}

